@PostMapping
public ResponseEntity<ProductResponse> create(@Valid @RequestBody ProductRequest request) {
    ProductResponse product = catalog.create(request);
    return ResponseEntity.created(URI.create("/api/products/" + product.sku())).body(product);
}

@PutMapping("/{sku}")
public ProductResponse update(@PathVariable String sku, @Valid @RequestBody ProductRequest request) {
    return catalog.update(sku, request);
}

// Deleting keeps the row (orders point at it) and takes the product off sale.
@DeleteMapping("/{sku}")
@ResponseStatus(HttpStatus.NO_CONTENT)
public void delete(@PathVariable String sku) {
    catalog.deactivate(sku);
}

@PostMapping("/{sku}/stock")
public ProductResponse adjustStock(@PathVariable String sku, @Valid @RequestBody StockAdjustment adjustment) {
    return catalog.adjustStock(sku, adjustment.change());
}

/**
 * The body of POST /api/products and PUT /api/products/{sku}. Numbers are wrapper types, so a
 * missing field arrives as null and fails @NotNull with a clear message, instead of failing
 * to parse (Jackson 3 refuses to put null into a primitive).
 */
public record ProductRequest(
        @NotNull @Pattern(regexp = "[A-Z]{2}-\\d{3}", message = "must look like AB-123") String sku,
        @NotBlank @Size(max = 120) String name,
        @Size(max = 2000) String description,
        @NotNull @Positive @Max(10_000_000) Long priceCents,
        @NotNull @PositiveOrZero @Max(100_000) Integer stock,
        @NotBlank String category,
        Boolean active) {

    // Optional fields get their defaults here, before validation runs.
    public ProductRequest {
        description = description == null ? "" : description.strip();
        active = active == null ? Boolean.TRUE : active;
    }
}

/** An account as clients see it. The password hash stays behind. */
public record CustomerResponse(long id, String email, String name, Role role, Instant createdAt) {

    public static CustomerResponse from(Customer customer) {
        return new CustomerResponse(customer.getId(), customer.getEmail(), customer.getName(),
                customer.getRole(), customer.getCreatedAt());
    }
}

/** One line of a new order: which product and how many. */
public record LineRequest(
        @NotNull @Pattern(regexp = "[A-Z]{2}-\\d{3}", message = "must look like AB-123") String sku,
        @NotNull @Positive @Max(50) Integer quantity) {
}

